108:     const g = c.createGain(); g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(vol, t + .02); g.gain.exponentialRampToValueAtTime(.0001, t + 2.4)
109:     const f = c.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 1100
110:     o.connect(f); f.connect(g); g.connect(this.musicBus); g.connect(this.reverb)
111:     o.start(t); o.stop(t + 2.5)
112:   }
113: 
114:   _thump(vol) {
115:     const c = this.ctx, t = c.currentTime
116:     const o = c.createOscillator(); o.type = 'sine'; o.frequency.setValueAtTime(95, t); o.frequency.exponentialRampToValueAtTime(38, t + .18)
117:     const g = c.createGain(); g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(.0001, t + .22)
118:     o.connect(g); g.connect(this.musicBus); o.start(t); o.stop(t + .24)
119:   }
120: 
121:   _tone(freq, dur, type = 'sine', vol = .15, slide = 0, when = 0) {
122:     if (!this.ctx) return
123:     const c = this.ctx, t = c.currentTime + when
124:     const o = c.createOscillator(); o.type = type; o.frequency.setValueAtTime(freq, t)
125:     if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slide), t + dur)
126:     const g = c.createGain(); g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(vol, t + .008); g.gain.exponentialRampToValueAtTime(.0001, t + dur)
127:     o.connect(g); g.connect(this.sfxBus); o.start(t); o.stop(t + dur + .02)
128:   }
129: 
130:   _noiseHit(dur = .18, vol = .12, filterFreq = 1200, type = 'bandpass') {
131:     if (!this.ctx || !this._noise) return
132:     const c = this.ctx, t = c.currentTime
133:     const src = c.createBufferSource(); src.buffer = this._noise
134:     const f = c.createBiquadFilter(); f.type = type; f.frequency.setValueAtTime(filterFreq, t); f.frequency.exponentialRampToValueAtTime(Math.max(80, filterFreq * .25), t + dur); f.Q.value = 1.2
135:     const g = c.createGain(); g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(.0001, t + dur)
136:     src.connect(f); f.connect(g); g.connect(this.sfxBus)
137:     src.start(t); src.stop(t + dur + .02)
138:   }
139: 
140:   unlock() { this.init() }
141:   setMuted(v) { this.muted = v; if (this.master) this.master.gain.value = v ? 0 : .55 }
142: 
143:   click() { this._tone(720, .05, 'triangle', .05, -120) }
144:   confirm() { this._tone(440, .18, 'sine', .08, 220); this._tone(660, .25, 'sine', .05, 110, .06) }
145:   back() { this._tone(330, .12, 'sine', .05, -80) }
146:   swing() { this._noiseHit(.14, .17, 2600); this._tone(240, .09, 'triangle', .04, -90) }
147:   hit() { this._tone(120, .1, 'square', .11, -60); this._noiseHit(.1, .12, 1800) }
148:   crit() { this._tone(880, .12, 'square', .07, 420); this._noiseHit(.16, .16, 3200) }
149:   shoot() { this._tone(880, .16, 'triangle', .07, -520); this._tone(1320, .1, 'sine', .03, -700) }
150:   dash() { this._noiseHit(.24, .12, 900, 'highpass'); this._tone(180, .18, 'sine', .05, 220) }
151:   hurt() { this._tone(160, .2, 'sawtooth', .1, -90); this._noiseHit(.18, .14, 700) }
152:   pickup() { this._tone(880, .1, 'sine', .05, 220); this._tone(1320, .18, 'sine', .04, 180, .05) }
153:   heal() { [440, 554, 659].forEach((f, i) => this._tone(f, .5, 'sine', .05, 20, i * .08)) }
154:   death() { this._tone(220, 1.4, 'sawtooth', .1, -170); this._noiseHit(1.1, .08, 500) }
155:   bossRoar() { this._tone(70, 1.2, 'sawtooth', .16, -20); this._noiseHit(.9, .16, 300, 'lowpass') }
156:   dialogue() { [523, 659, 784].forEach((f, i) => this._tone(f, .8, 'sine', .035, 10, i * .09)) }
157:   portal() { this._tone(196, 1.2, 'sine', .06, 390); this._tone(294, 1.4, 'triangle', .03, 240, .08) }
158:   levelUp() { [440, 554, 659, 880].forEach((f, i) => this._tone(f, .6, 'triangle', .05, 10, i * .07)) }
159:   bossPhase() { this._tone(90, .8, 'sawtooth', .12, 40); this._noiseHit(.5, .1, 900) }
160: }

