/* ---------- HUD ---------- */
#hud{position:fixed;inset:0;z-index:10;pointer-events:none;display:flex;flex-direction:column;justify-content:space-between;padding:18px 22px 18px}
.hud-top{display:flex;align-items:flex-start;gap:20px;justify-content:space-between}
.hud-hero{display:flex;align-items:center;gap:13px;pointer-events:auto;padding:8px 16px 8px 8px;background:linear-gradient(100deg,rgba(12,8,18,.9),rgba(12,8,18,.18));border:1px solid rgba(217,185,120,.16);min-width:300px}
