.bar.mana i{background:linear-gradient(90deg,#4d2d96,#9a6bff 70%,#d3b8ff)}
.bar span{position:absolute;right:5px;top:50%;transform:translateY(-50%);font-size:8px;letter-spacing:.12em;color:rgba(255,255,255,.8);text-shadow:0 1px 3px #000;font-weight:600}
.hud-center{text-align:center;padding-top:4px;flex:1}
