.boss-label em{font-style:normal;font-size:9px;letter-spacing:.2em;color:var(--gold)}
.boss-bar{height:8px;border:1px solid rgba(224,80,113,.4);background:rgba(0,0,0,.6);position:relative}
.boss-bar i{position:absolute;inset:1px auto 1px 1px;background:linear-gradient(90deg,#6e1230,#d63b60,#ff9ab0);transition:width .15s;box-shadow:0 0 12px rgba(224,80,113,.5)}
#interact-prompt{position:fixed;left:50%;bottom:118px;transform:translateX(-50%);display:flex;align-items:center;gap:10px;padding:9px 17px;background:rgba(8,5,12,.9);border:1px solid var(--line-strong);font-size:10px;letter-spacing:.22em;text-transform:uppercase;color:var(--gold-bright);box-shadow:0 8px 30px rgba(0,0,0,.7);animation:promptPulse 2s ease-in-out infinite}
