.art-lock b{font-family:var(--serif);font-size:16px;letter-spacing:.3em;color:var(--gold-bright)}
.art-lock p{font-size:10px;letter-spacing:.14em;color:var(--muted);max-width:240px;line-height:1.6;text-transform:uppercase}
.art-caption{position:absolute;left:0;right:0;bottom:0;z-index:3;padding:24px 20px 12px;font-family:var(--serif);font-size:11px;letter-spacing:.2em;text-transform:uppercase;color:rgba(240,230,216,.55);background:linear-gradient(0deg,rgba(4,3,7,.9),transparent);text-align:center}
.art-notes{display:flex;flex-direction:column;min-height:0;padding:6px 0}
.art-title-row{display:flex;align-items:flex-start;justify-content:space-between;gap:10px;border-bottom:1px solid rgba(217,185,120,.2);padding-bottom:14px}
.art-title-row h3{font-family:var(--serif);font-weight:400;font-size:clamp(24px,2.4vw,34px);letter-spacing:.04em;color:var(--gold-bright);margin-top:2px}
