.art-lore{font-size:11.5px;line-height:1.8;letter-spacing:.02em;color:rgba(240,230,216,.65);overflow-y:auto;padding-right:6px}
.art-meta{display:flex;justify-content:space-between;gap:10px;margin-top:auto;padding-top:16px;border-top:1px solid rgba(255,255,255,.07);font-size:8.5px;letter-spacing:.18em;color:var(--gold);text-transform:uppercase}
.art-meta span:last-child{color:var(--crimson-bright)}
.memory-log{margin-top:14px;padding:12px 14px;border-left:1px solid rgba(154,107,255,.4);background:rgba(154,107,255,.05);font-family:var(--serif);font-style:italic;font-size:12px;line-height:1.6;color:rgba(220,200,255,.7);display:none}
