.gallery-screen{background:rgba(4,3,7,.9);backdrop-filter:blur(10px);flex-direction:column;padding:34px 4vw 28px}
.gallery-and-close{position:absolute;right:26px;top:22px;z-index:5}
.gallery-head{position:relative;z-index:2;max-width:660px;margin-bottom:18px}
.gallery-head h2{font-family:var(--serif);font-weight:400;font-size:clamp(28px,3.2vw,46px);letter-spacing:.03em;color:var(--gold-bright);margin-top:2px}
.gallery-head h2 em{color:var(--crimson-bright);font-style:italic}
.gallery-head p{font-size:11px;line-height:1.6;letter-spacing:.06em;color:var(--muted);margin-top:7px;max-width:520px}
.gallery-body{position:relative;z-index:2;display:grid;grid-template-columns:250px 1fr;gap:28px;flex:1;min-height:0}
.gallery-rail{display:flex;flex-direction:column;gap:9px;padding-top:4px}
.gallery-tab{position:relative;display:flex;align-items:center;gap:11px;padding:8px;border:1px solid rgba(255,255,255,.07);background:rgba(255,255,255,.015);transition:.2s;text-align:left;overflow:hidden}
.gallery-tab img{width:52px;height:64px;object-fit:cover;object-position:50% 8%;filter:saturate(.8)}
.gallery-tab .gt-name{font-family:var(--serif);font-size:15px;letter-spacing:.04em;color:rgba(240,230,216,.8)}
.gallery-tab .gt-sub{font-size:8px;letter-spacing:.16em;text-transform:uppercase;color:var(--muted);margin-top:3px}
.gallery-tab .gt-state{margin-left:auto;font-size:8px;letter-spacing:.14em;color:var(--gold);writing-mode:vertical-rl}
.gallery-tab.locked img{filter:grayscale(1) brightness(.32) blur(1px)}
.gallery-tab.locked .gt-name{color:rgba(240,230,216,.4)}
.gallery-tab:hover,.gallery-tab.active{border-color:rgba(217,185,120,.5);background:rgba(180,43,75,.1);transform:translateX(3px)}
.gallery-tab.active::before{content:"";position:absolute;left:0;top:0;bottom:0;width:2px;background:var(--gold)}
.gallery-stage{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(250px,1fr);gap:26px;min-height:0}
.art-frame{position:relative;min-height:0;height:100%;background:radial-gradient(ellipse at 50% 30%,rgba(68,32,80,.32),rgba(5,4,9,.96));border:1px solid rgba(217,185,120,.22);display:flex;align-items:center;justify-content:center;overflow:hidden;box-shadow:0 20px 60px rgba(0,0,0,.6)}
.art-frame::before{content:"";position:absolute;inset:9px;border:1px solid rgba(217,185,120,.1);pointer-events:none;z-index:3}
.art-frame img{height:100%;width:100%;object-fit:contain;transition:filter .4s,transform .8s ease;position:relative;z-index:1}
.art-frame:hover img{transform:scale(1.015)}
.art-frame.sealed img{filter:grayscale(1) brightness(.25) blur(8px);transform:scale(1.06)}
.frame-corner{position:absolute;width:26px;height:26px;border-color:rgba(217,185,120,.6);border-style:solid;z-index:4;pointer-events:none}
.frame-corner.tl{left:7px;top:7px;border-width:1px 0 0 1px}.frame-corner.tr{right:7px;top:7px;border-width:1px 1px 0 0}
.frame-corner.bl{left:7px;bottom:7px;border-width:0 0 1px 1px}.frame-corner.br{right:7px;bottom:7px;border-width:0 1px 1px 0}
.art-lock{position:absolute;z-index:4;inset:0;display:none;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:4px;background:radial-gradient(ellipse,rgba(8,5,13,.35),rgba(5,3,8,.65))}
.art-frame.sealed .art-lock{display:flex}
.art-lock .lock-glyph{font-size:44px;color:var(--gold);opacity:.8;text-shadow:0 0 30px rgba(217,185,120,.4)}
.art-lock b{font-family:var(--serif);font-size:16px;letter-spacing:.3em;color:var(--gold-bright)}
.art-lock p{font-size:10px;letter-spacing:.14em;color:var(--muted);max-width:240px;line-height:1.6;text-transform:uppercase}
.art-caption{position:absolute;left:0;right:0;bottom:0;z-index:3;padding:24px 20px 12px;font-family:var(--serif);font-size:11px;letter-spacing:.2em;text-transform:uppercase;color:rgba(240,230,216,.55);background:linear-gradient(0deg,rgba(4,3,7,.9),transparent);text-align:center}
.art-notes{display:flex;flex-direction:column;min-height:0;padding:6px 0}
.art-title-row{display:flex;align-items:flex-start;justify-content:space-between;gap:10px;border-bottom:1px solid rgba(217,185,120,.2);padding-bottom:14px}
.art-title-row h3{font-family:var(--serif);font-weight:400;font-size:clamp(24px,2.4vw,34px);letter-spacing:.04em;color:var(--gold-bright);margin-top:2px}
.art-quote{font-family:var(--serif);font-style:italic;font-size:16px;line-height:1.55;color:var(--crimson-bright);margin:18px 0 12px}
.art-lore{font-size:11.5px;line-height:1.8;letter-spacing:.02em;color:rgba(240,230,216,.65);overflow-y:auto;padding-right:6px}
.art-meta{display:flex;justify-content:space-between;gap:10px;margin-top:auto;padding-top:16px;border-top:1px solid rgba(255,255,255,.07);font-size:8.5px;letter-spacing:.18em;color:var(--gold);text-transform:uppercase}
.art-meta span:last-child{color:var(--crimson-bright)}
.memory-log{margin-top:14px;padding:12px 14px;border-left:1px solid rgba(154,107,255,.4);background:rgba(154,107,255,.05);font-family:var(--serif);font-style:italic;font-size:12px;line-height:1.6;color:rgba(220,200,255,.7);display:none}
.memory-log.show{display:block}
.art-modal{position:fixed;inset:0;z-index:70;background:rgba(3,2,6,.97);display:none;align-items:center;justify-content:center;padding:4vh 4vw}
.art-modal.active{display:flex}

Gallery mobile: also the gallery screen padding 20px 16px; header h2 28px. The close button at right 26 top 22 overlaps title. Let's add mobile:
