.shop-screen{padding:8px}
.shop-shell{width:100%;height:calc(100dvh - 16px);max-height:none;grid-template-columns:1fr;grid-template-rows:min(18vh,112px) 1fr}
.shop-portrait-side{border-right:0;border-bottom:1px solid rgba(217,185,120,.16)}
.shop-portrait-side img{object-position:50% 10%;-webkit-mask-image:linear-gradient(to bottom,#000 0%,#000 80%,transparent 100%);mask-image:linear-gradient(to bottom,#000 0%,#000 80%,transparent 100%)}
.shop-speech{bottom:6px;left:8px;right:auto;max-width:58%;padding:5px 8px}
.shop-speech .eyebrow{font-size:7px}
.shop-speech p{display:none}
.shop-main{padding:10px 12px 8px}
.shop-head{gap:8px;align-items:center}
