.shop-currency small{font-size:6px}
.close-btn{width:34px;height:34px;flex:none}
.shop-sub{font-size:9px;margin:5px 0 7px;line-height:1.35}
.shop-grid{grid-template-columns:1fr;gap:7px;padding-right:2px;min-height:0}
.shop-item{min-height:62px;padding:8px;gap:8px}
.shop-icon{width:38px;height:38px;font-size:18px}
.shop-info b{font-size:14px}
.shop-info p{font-size:9px;line-height:1.35;margin-top:2px}
.shop-pips{margin-top:5px}
.shop-buy{gap:5px}
.shop-buy button{min-height:28px;padding:6px 9px}
.shop-foot{padding-top:7px;margin-top:5px;min-height:42px}
.shop-foot span{max-width:55%;font-size:9px;line-height:1.35;text-align:right}
.shop-foot .ghost-btn{padding:8px 10px;font-size:8px}

